package com.jgraph.analyzer.parser;

/**
 * One case per kind of bridge method generated by javac (ADR-0007): generics, bounded generics, covariant return type
 * and visibility. Each subclass method below gets a compiler-generated bridge next to it.
 */
public class BridgeFixture {

    public static final Class<?>[] CLASSES = {
            Repository.class,
            Order.class,
            OrderRepository.class,
            Entity.class,
            Invoice.class,
            AbstractCrudService.class,
            InvoiceService.class,
            Animal.class,
            Dog.class,
            HiddenBase.class,
            PublicFacade.class,
            OrderController.class
    };

    // --- Generics: bridge save(Object) -> save(Order) ---

    public interface Repository<T> {
        void save(T entity);
    }

    public static class Order {
    }

    public static class OrderRepository implements Repository<Order> {
        @Override
        public void save(Order order) {
        }
    }

    // --- Bounded generics: erased to the bound, bridge persist(Entity) -> persist(Invoice) ---

    public static class Entity {
    }

    public static class Invoice extends Entity {
    }

    public abstract static class AbstractCrudService<E extends Entity> {
        public abstract void persist(E entity);
    }

    public static class InvoiceService extends AbstractCrudService<Invoice> {
        @Override
        public void persist(Invoice invoice) {
        }
    }

    // --- Covariant return type: bridge Animal copy() -> Dog copy() ---

    public static class Animal {
        public Animal copy() {
            return new Animal();
        }
    }

    public static class Dog extends Animal {
        @Override
        public Dog copy() {
            return new Dog();
        }
    }

    // --- Visibility: public class inheriting a public method from a package-private class ---

    static class HiddenBase {
        public void greet() {
        }
    }

    public static class PublicFacade extends HiddenBase {
        // greet() is not redeclared: javac adds a bridge greet() -> HiddenBase.greet()
    }

    // --- Caller through the generic interface ---

    public static class OrderController {
        private final Repository<Order> repository = new OrderRepository();

        public void submit(Order order) {
            repository.save(order);
        }
    }
}
